import { bookLab, createMemoryRepo } from '../src/booking/service.js';
import { createFakeMailer } from '../test/support/fakes.js';

const input = { lab: 'BE-201', date: '2026-11-16', seats: 31, role: 'STUDENT', start: '08:00', end: '10:00', email: 'an@fpt.edu.vn' };

// Starter: ONE smoke test — it only checks that the code under test can be imported. It kills no mutant.
// Write the real tests below (see the task). Khởi đầu: MỘT test khói — chỉ kiểm code nạp được, không diệt đột biến nào.
describe('starter', () => {
  it('the code under test can be imported', () => {
    expect(bookAndNotify).toBeDefined();
    expect(APPROVER).toBeDefined();
    expect(bookLab).toBeDefined();
    expect(createMemoryRepo).toBeDefined();
    expect(createFakeMailer).toBeDefined();
  });
